import{_ as i,o as e,c as t,a2 as s}from"./chunks/framework.BXA5Pi9t.js";const h=JSON.parse('{"title":"2019-03-20 :: Ceph Testing meeting","description":"","frontmatter":{"title":"2019-03-20 :: Ceph Testing meeting","date":"2019-03-20T00:00:00.000Z","updated":"2019-04-15T00:00:00.000Z","tags":["Ceph","分布式存储","测试","开发","社区"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/2019-03-20_-_-_Ceph_Testing_meeting.md","filePath":"posts/2019/2019-03-20_-_-_Ceph_Testing_meeting.md","lastUpdated":1780460162000}'),n={name:"posts/2019/2019-03-20_-_-_Ceph_Testing_meeting.md"};function o(p,l,a,r,g,_){return e(),t("div",null,[...l[0]||(l[0]=[s('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议时间</strong>： 未知 <strong>与会人员</strong>： 多名参与者，包括Zach、Sofia团队成员、OVH团队成员等 <strong>会议主题</strong>： Ceph分布式存储项目进展、测试环境搭建、新特性讨论、PR审查等</p><p><strong>会议关键细节</strong>：</p><ul><li><strong>Pepsi项目</strong>： <ul><li>Zach正在开发为openSUSE发行版提供Ceph部署和测试环境的Pepsi项目。</li><li>项目面临镜像配置错误导致无法登录等问题。</li><li>讨论了利用OVH资源进行测试的可能性，并寻求社区成员的帮助。</li></ul></li><li><strong>Ceph测试环境</strong>： <ul><li>讨论了使用Tautology进行Ceph测试的想法，该工具旨在自动化测试流程。</li><li>认为Tautology可能是一个有用的工具，可以改进测试过程。</li></ul></li><li><strong>Inspect特性</strong>： <ul><li>讨论了Inspect特性，该特性可以分析Pepsi测试套件并生成测试用例。</li><li>认为Inspect特性可以替代describe特性。</li></ul></li><li><strong>PR审查</strong>： <ul><li>讨论了多个PR，包括Pepsi项目的PR和Inspect特性的PR。</li><li>参与者对PR进行了审查，并提出了反馈意见。</li></ul></li></ul><p><strong>讨论的主要议题</strong>：</p><ul><li>如何改进Ceph测试流程。</li><li>如何使用Tautology和Inspect特性。</li><li>如何解决Pepsi项目中遇到的问题。</li></ul><p><strong>决定的事项</strong>：</p><ul><li>继续使用Tautology和Inspect特性。</li><li>尝试使用OVH资源进行测试。</li><li>解决Pepsi项目中遇到的问题。</li></ul><p><strong>后续行动计划</strong>：</p><ul><li>Zach将继续开发Pepsi项目。</li><li>参与者将继续审查PR。</li><li>讨论如何使用Tautology和Inspect特性。</li><li>讨论Ceph Nautilus版本的发布。</li><li>讨论Ceph社区会议的安排。</li></ul><p><strong>其他事项</strong>：</p><ul><li>讨论了Ceph Nautilus版本的发布。</li><li>讨论了Ceph社区会议的安排。</li><li>讨论了Ceph在不同存储环境中的应用，包括openSUSE、Nautilus等。</li><li>讨论了Ceph与其他项目的集成，如Tautology、Inspect等。</li><li>讨论了Ceph社区成员间的沟通和协作。</li></ul>',12)])])}const c=i(n,[["render",o]]);export{h as __pageData,c as default};
